<?php
/** AI fundamentals: what AI, ML, deep learning and generative AI are, data, training and inference, LLMs and their limits. */

return [
    'id' => 'ai-base', 'family' => 'ai', 'after' => null,
    'title' => L('Fondamenti di AI', 'AI Fundamentals'), 'short' => L('AI base', 'AI Basics'), 'level' => L('Base', 'Basics'),
    'desc' => L('Che cos’è davvero l’intelligenza artificiale: machine learning, deep learning, AI generativa, dati, addestramento, modelli linguistici e loro limiti.', 'What artificial intelligence really is: machine learning, deep learning, generative AI, data, training, language models and their limits.'),
    'lessons' => [
        lesson('what', L('Che cos’è l’AI', 'What AI is'), [
            P('**Intelligenza artificiale** è il nome largo per i sistemi che svolgono compiti che di solito richiedono intelligenza umana: riconoscere immagini, capire testi, tradurre, giocare, decidere. Dentro ci sono cerchi sempre più piccoli.', '**Artificial intelligence** is the broad name for systems that perform tasks that usually need human intelligence: recognising images, understanding text, translating, playing, deciding. Inside it sit ever smaller circles.'),
            P('Il **machine learning** (ML) è l’AI che impara dagli esempi invece di seguire regole scritte a mano. Il **deep learning** è il ML fatto con reti neurali a molti strati. L’**AI generativa** usa il deep learning per *creare* contenuti nuovi: testo, immagini, audio, codice.', '**Machine learning** (ML) is AI that learns from examples instead of following hand-written rules. **Deep learning** is ML done with many-layered neural networks. **Generative AI** uses deep learning to *create* new content: text, images, audio, code.'),
            C('AI
└── Machine learning        impara dai dati
    └── Deep learning       reti neurali profonde
        └── AI generativa   crea testo, immagini, audio', 'text'),
            Tip('Un filtro antispam a regole (“se contiene ‘vinci subito’ allora spam”) è AI ma non ML. Uno che impara da migliaia di email etichettate è ML.', 'A rule-based spam filter (“if it says ‘win now’ then spam”) is AI but not ML. One that learns from thousands of labelled emails is ML.'),
        ], [
            Q('w1', L('Che cosa distingue il machine learning?', 'What sets machine learning apart?'), [L('Impara dagli esempi', 'It learns from examples'), L('Usa solo regole scritte a mano', 'It only uses hand-written rules'), L('Funziona senza dati', 'It works without data'), L('È sempre generativo', 'It is always generative')], 0, L('Le regole le ricava dai dati.', 'It derives the rules from data.')),
            Q('w2', L('Il deep learning è…', 'Deep learning is…'), [L('ML con reti neurali a molti strati', 'ML with many-layered neural networks'), L('Un database molto grande', 'A very large database'), L('L’opposto del ML', 'The opposite of ML'), L('Un linguaggio di programmazione', 'A programming language')], 0, L('“Profondo” per i tanti strati.', '“Deep” because of the many layers.')),
            Q('w3', L('Quale di questi è AI generativa?', 'Which of these is generative AI?'), [L('Un modello che scrive un racconto', 'A model that writes a story'), L('Un termostato', 'A thermostat'), L('Un foglio di calcolo', 'A spreadsheet'), L('Un filtro a regole fisse', 'A fixed-rule filter')], 0, L('Crea contenuti nuovi.', 'It creates new content.')),
        ], task('text', L('Scrivi su tre righe un esempio per ciascuno: una riga che inizia con `ML:`, una con `DL:` e una con `GenAI:`.', 'Write one example of each on three lines: a line starting with `ML:`, one with `DL:` and one with `GenAI:`.'), "ML: \nDL: \nGenAI: ", [re('^ML:\s*\S.{3,}', L('Un esempio di ML', 'An ML example')), re('^DL:\s*\S.{3,}', L('Un esempio di deep learning', 'A deep learning example')), re('^GenAI:\s*\S.{3,}', L('Un esempio di AI generativa', 'A generative AI example'))], '', "ML: prevedere il prezzo di una casa\nDL: riconoscere i volti nelle foto\nGenAI: scrivere una mail con un chatbot"), [
            dMatch(pMatch(), [['AI', L('Il campo intero', 'The whole field')], ['ML', L('Impara dai dati', 'Learns from data')], ['Deep learning', L('Reti neurali profonde', 'Deep neural networks')], [L('AI generativa', 'Generative AI'), L('Crea contenuti', 'Creates content')]], L('I cerchi uno dentro l’altro.', 'Circles one inside another.')),
            dFlash(pFlash(), [[L('Tutto il ML è AI', 'All ML is AI'), true], [L('Tutta l’AI è deep learning', 'All AI is deep learning'), false], [L('L’AI generativa usa il deep learning', 'Generative AI uses deep learning'), true], [L('Un sistema a regole fisse è machine learning', 'A fixed-rule system is machine learning'), false]], L('Dal generale al particolare.', 'From general to specific.')),
        ]),
        lesson('data', L('Dati, addestramento e inferenza', 'Data, training and inference'), [
            P('Un modello di ML nasce in due fasi. Nell’**addestramento** (training) guarda moltissimi esempi e regola i suoi **parametri** per sbagliare sempre meno. Nell’**inferenza** usa i parametri imparati per rispondere su dati nuovi.', 'An ML model is born in two phases. In **training** it looks at many examples and adjusts its **parameters** to make fewer and fewer mistakes. In **inference** it uses the learned parameters to answer on new data.'),
            C('dati di esempio ──► addestramento ──► modello (parametri)
nuovo dato ─────────────────────────► modello ──► previsione', 'text'),
            P('La qualità dei dati conta più di tutto: dati pochi, sporchi o sbilanciati producono un modello scarso o ingiusto (“garbage in, garbage out”). Per misurarlo onestamente si tiene da parte un **test set** che il modello non ha mai visto.', 'Data quality matters most: little, dirty or skewed data produces a poor or unfair model (“garbage in, garbage out”). To measure it honestly you keep aside a **test set** the model has never seen.'),
        ], [
            Q('d1', L('Che cosa succede durante l’addestramento?', 'What happens during training?'), [L('Il modello regola i parametri sugli esempi', 'The model tunes its parameters on examples'), L('Il modello risponde agli utenti', 'The model answers users'), L('Si cancellano i dati', 'The data is deleted'), L('Si scrive il codice dell’app', 'The app code is written')], 0, L('L’inferenza viene dopo.', 'Inference comes after.')),
            Q('d2', L('Che cos’è l’inferenza?', 'What is inference?'), [L('Usare il modello su dati nuovi', 'Using the model on new data'), L('Raccogliere dati', 'Collecting data'), L('Ripulire i dati', 'Cleaning the data'), L('Comprare GPU', 'Buying GPUs')], 0, L('È quello che fai quando chatti con un modello.', 'It is what you do when you chat with a model.')),
            Q('d3', L('Perché si tiene da parte un test set?', 'Why keep a test set aside?'), [L('Per misurare il modello su dati mai visti', 'To measure the model on unseen data'), L('Per addestrare più velocemente', 'To train faster'), L('Per risparmiare spazio', 'To save space'), L('Per fare un backup', 'To make a backup')], 0, L('Altrimenti il voto sarebbe falsato.', 'Otherwise the score would be inflated.')),
        ], task('text', L('Indica per ciascuna attività se è `training` o `inferenza`, una per riga nel formato `attività: fase`. Attività: `chatbot risponde`, `il modello impara da 1 milione di foto`.', 'For each activity say whether it is `training` or `inference`, one per line as `activity: phase`. Activities: `chatbot answers`, `model learns from 1 million photos`.'), '', [re('(chatbot risponde|chatbot answers)\s*:\s*(inferenza|inference)', L('Il chatbot fa inferenza', 'The chatbot does inference')), re('(il modello impara|model learns)[^:\n]*:\s*training', L('Imparare è training', 'Learning is training'))], '', "chatbot risponde: inferenza\nil modello impara da 1 milione di foto: training"), [
            dOrder(pSort(), [L('Raccogli i dati', 'Collect the data'), L('Pulisci ed etichetta', 'Clean and label'), L('Addestra il modello', 'Train the model'), L('Valuta sul test set', 'Evaluate on the test set'), L('Usa il modello (inferenza)', 'Use the model (inference)')], L('Il ciclo di vita di un modello.', 'A model’s life cycle.')),
            dFlash(pFlash(), [[L('Dati migliori battono spesso modelli più grandi', 'Better data often beats bigger models'), true], [L('Il test set si usa anche per addestrare', 'The test set is also used for training'), false], [L('I parametri si regolano durante il training', 'Parameters are tuned during training'), true], [L('L’inferenza cambia i parametri del modello', 'Inference changes the model’s parameters'), false]], L('Prima si impara, poi si usa.', 'First learn, then use.')),
        ]),
        lesson('llm', L('Come funziona un modello linguistico', 'How a language model works'), [
            P('Un **LLM** (Large Language Model) come quelli dietro ChatGPT, Claude o Gemini è addestrato su enormi quantità di testo a fare una cosa sola: prevedere il **token** successivo. Un token è un pezzo di parola: “intelligenza” può diventare “intel” + “ligenza”.', 'An **LLM** (Large Language Model) like those behind ChatGPT, Claude or Gemini is trained on huge amounts of text to do one thing: predict the next **token**. A token is a piece of a word: “intelligence” may become “intel” + “ligence”.'),
            C('“Il gatto sale sul” → tetto (62%) · tavolo (21%) · divano (9%) …', 'text'),
            P('Ripetendo la previsione token dopo token il modello scrive frasi intere. Dopo il pre-addestramento viene rifinito con esempi di conversazione e con il feedback umano, perché segua le istruzioni e risponda in modo utile e sicuro. La **finestra di contesto** è quanto testo il modello può considerare in una volta.', 'Repeating the prediction token after token, the model writes whole sentences. After pre-training it is refined with conversation examples and human feedback, so it follows instructions and answers helpfully and safely. The **context window** is how much text the model can consider at once.'),
        ], [
            Q('l1', L('Che cosa fa, alla base, un LLM?', 'What does an LLM do, at its core?'), [L('Prevede il token successivo', 'Predicts the next token'), L('Cerca la risposta in un database', 'Looks the answer up in a database'), L('Copia pagine web intere', 'Copies whole web pages'), L('Esegue regole scritte a mano', 'Runs hand-written rules')], 0, L('Un token dopo l’altro.', 'One token after another.')),
            Q('l2', L('Che cos’è un token?', 'What is a token?'), [L('Un pezzo di testo, spesso parte di una parola', 'A piece of text, often part of a word'), L('Una password', 'A password'), L('Una moneta digitale', 'A digital coin'), L('Una riga di codice', 'A line of code')], 0, L('Si paga e si misura in token.', 'You pay and measure in tokens.')),
            Q('l3', L('Che cos’è la finestra di contesto?', 'What is the context window?'), [L('Quanto testo il modello considera in una volta', 'How much text the model considers at once'), L('La finestra della chat', 'The chat window'), L('Il tempo di risposta', 'The response time'), L('Il numero di utenti', 'The number of users')], 0, L('Oltre quel limite il testo non entra.', 'Beyond that limit text does not fit.')),
        ], task('text', L('Spiega in una frase che cosa fa un LLM, usando le parole `token` e `prevedere` (o `predict`).', 'Explain in one sentence what an LLM does, using the words `token` and `predict` (or `prevedere`).'), '', [re('token', L('Parli di token', 'You mention tokens')), re('preved|predict', L('Parli di previsione', 'You mention prediction'))], '', 'Un LLM scrive un testo prevedendo un token alla volta, il più probabile dopo quelli precedenti.'), [
            dMatch(pMatch(), [['LLM', L('Modello linguistico grande', 'Large language model')], ['Token', L('Pezzo di testo', 'Piece of text')], [L('Contesto', 'Context'), L('Testo considerato insieme', 'Text considered together')], [L('Pre-addestramento', 'Pre-training'), L('Imparare da tanto testo', 'Learning from lots of text')], [L('Feedback umano', 'Human feedback'), L('Rifinire il comportamento', 'Refining behaviour')]], L('Il vocabolario degli LLM.', 'LLM vocabulary.')),
            dFlash(pFlash(), [[L('Un LLM legge parole intere, mai pezzi', 'An LLM reads whole words, never pieces'), false], [L('Un LLM scrive un token alla volta', 'An LLM writes one token at a time'), true], [L('La finestra di contesto è illimitata', 'The context window is unlimited'), false], [L('Il feedback umano aiuta a seguire le istruzioni', 'Human feedback helps follow instructions'), true]], L('Previsione, non magia.', 'Prediction, not magic.')),
        ]),
        lesson('limits', L('Limiti e allucinazioni', 'Limits and hallucinations'), [
            P('Un LLM produce testo **plausibile**, non necessariamente vero. Quando inventa fatti, citazioni o fonti con sicurezza si parla di **allucinazione**. Non è un bug raro: è una conseguenza di come funziona.', 'An LLM produces **plausible** text, not necessarily true text. When it confidently invents facts, quotes or sources it is called a **hallucination**. It is not a rare bug: it follows from how it works.'),
            P('Altri limiti: la **data di taglio** (non conosce i fatti successivi all’addestramento, se non può cercare sul web), i calcoli lunghi, i **bias** ereditati dai dati. Le difese: chiedere le fonti e controllarle, dare al modello i documenti giusti, verificare numeri e codice.', 'Other limits: the **knowledge cutoff** (it does not know events after training, unless it can search the web), long calculations, **biases** inherited from data. Defences: ask for sources and check them, give the model the right documents, verify numbers and code.'),
            Tip('Usa l’AI come un collega brillante ma distratto: ottimo per bozze e idee, da ricontrollare quando conta.', 'Treat AI like a brilliant but absent-minded colleague: great for drafts and ideas, to be double-checked when it matters.'),
        ], [
            Q('h1', L('Che cos’è un’allucinazione?', 'What is a hallucination?'), [L('Un’informazione inventata detta con sicurezza', 'Made-up information stated confidently'), L('Un errore di rete', 'A network error'), L('Un’immagine generata', 'A generated image'), L('Un modello spento', 'A model that is off')], 0, L('Plausibile non vuol dire vero.', 'Plausible does not mean true.')),
            Q('h2', L('Che cos’è la data di taglio?', 'What is the knowledge cutoff?'), [L('Il limite dei fatti che il modello conosce', 'The limit of facts the model knows'), L('La scadenza dell’abbonamento', 'The subscription expiry'), L('La lunghezza massima della risposta', 'The maximum answer length'), L('L’ora di manutenzione', 'The maintenance hour')], 0, L('Dopo quella data non sa, a meno che cerchi.', 'After that date it does not know, unless it searches.')),
            Q('h3', L('Qual è una buona difesa dalle allucinazioni?', 'What is a good defence against hallucinations?'), [L('Verificare le fonti citate', 'Checking the cited sources'), L('Fare domande più lunghe', 'Asking longer questions'), L('Usare il maiuscolo', 'Using capital letters'), L('Ripetere la domanda finché piace la risposta', 'Repeating the question until you like the answer')], 0, L('Le fonti si controllano.', 'Sources must be checked.')),
        ], task('text', L('Riscrivi questa richiesta in modo che riduca le allucinazioni: chiedi esplicitamente le `fonti` e di dire `non lo so` se non è sicuro. Richiesta: “Chi ha inventato il primo compilatore?”', 'Rewrite this request to reduce hallucinations: explicitly ask for `sources` and to say `I don’t know` if unsure. Request: “Who invented the first compiler?”'), 'Chi ha inventato il primo compilatore?', [re('compilator|compiler', L('Mantieni la domanda', 'You keep the question')), re('font[ie]|sources?', L('Chiedi le fonti', 'You ask for sources')), re('non lo so|non (sei|è) sicur|don.t know|not sure', L('Ammetti l’incertezza', 'You allow uncertainty'))], '', 'Chi ha inventato il primo compilatore? Indica le fonti e, se non sei sicuro, dimmi “non lo so”.'), [
            dMatch(pMatch(), [[L('Allucinazione', 'Hallucination'), L('Fatto inventato', 'Made-up fact')], [L('Data di taglio', 'Cutoff'), L('Fatti recenti sconosciuti', 'Recent facts unknown')], ['Bias', L('Pregiudizi dai dati', 'Prejudice from data')], [L('Verifica', 'Verification'), L('Controllare fonti e numeri', 'Checking sources and numbers')]], L('Conoscere i limiti per usarla bene.', 'Know the limits to use it well.')),
            dFlash(pFlash(), [[L('Un LLM può inventare una citazione', 'An LLM can invent a quote'), true], [L('Se risponde con sicurezza, è sicuramente vero', 'If it answers confidently, it is surely true'), false], [L('I dati di addestramento possono contenere pregiudizi', 'Training data can contain bias'), true], [L('Un LLM conosce sempre le notizie di oggi', 'An LLM always knows today’s news'), false]], L('Fiducia, ma con verifica.', 'Trust, but verify.')),
        ]),
        lesson('uses', L('Dove si usa l’AI', 'Where AI is used'), [
            P('L’AI è già ovunque: **classificazione** (spam, diagnosi da immagini), **previsione** (vendite, traffico, meteo), **raccomandazione** (film, prodotti), **visione** (volti, guida assistita), **linguaggio** (traduzione, riassunti, chatbot), **generazione** (testo, immagini, codice, musica).', 'AI is already everywhere: **classification** (spam, image diagnosis), **forecasting** (sales, traffic, weather), **recommendation** (films, products), **vision** (faces, driver assistance), **language** (translation, summaries, chatbots), **generation** (text, images, code, music).'),
            P('Prima di usarla chiediti: il compito ha dati a sufficienza? Un errore è grave? Serve una spiegazione della decisione? Per compiti ad alto rischio (salute, credito, giustizia) servono controlli umani e, in Europa, le regole dell’**AI Act**.', 'Before using it ask yourself: does the task have enough data? Is a mistake serious? Is an explanation of the decision needed? For high-risk tasks (health, credit, justice) you need human oversight and, in Europe, the rules of the **AI Act**.'),
        ], [
            Q('u1', L('Suggerire un film in base a quelli visti è…', 'Suggesting a film based on those you watched is…'), [L('Raccomandazione', 'Recommendation'), L('Visione', 'Vision'), L('Traduzione', 'Translation'), L('Compressione', 'Compression')], 0, L('Impara dai gusti simili.', 'It learns from similar tastes.')),
            Q('u2', L('Quale compito è ad alto rischio?', 'Which task is high risk?'), [L('Decidere chi riceve un prestito', 'Deciding who gets a loan'), L('Suggerire una canzone', 'Suggesting a song'), L('Correggere un refuso', 'Fixing a typo'), L('Scegliere un emoji', 'Picking an emoji')], 0, L('Tocca diritti e opportunità.', 'It touches rights and opportunities.')),
            Q('u3', L('Quale legge europea regola l’AI?', 'Which European law regulates AI?'), ['AI Act', 'GDPR Act', 'Digital Cookie Act', 'Code Act'], 0, L('Classifica i sistemi per livello di rischio.', 'It classifies systems by risk level.')),
        ], task('text', L('Abbina tre usi al loro tipo, uno per riga come `uso: tipo`. Usi: `filtro antispam`, `previsione delle vendite`, `traduzione automatica`. Tipi: classificazione, previsione, linguaggio.', 'Match three uses to their type, one per line as `use: type`. Uses: `spam filter`, `sales forecast`, `machine translation`. Types: classification, forecasting, language.'), '', [re('(antispam|spam)[^:\n]*:\s*(classificazione|classification)', L('Lo spam è classificazione', 'Spam is classification')), re('(vendite|sales)[^:\n]*:\s*(previsione|forecast)', L('Le vendite sono previsione', 'Sales are forecasting')), re('(traduzione|translation)[^:\n]*:\s*(linguaggio|language)', L('La traduzione è linguaggio', 'Translation is language'))], '', "filtro antispam: classificazione\nprevisione delle vendite: previsione\ntraduzione automatica: linguaggio"), [
            dMatch(pMatch(), [[L('Filtro antispam', 'Spam filter'), L('Classificazione', 'Classification')], [L('Meteo di domani', 'Tomorrow’s weather'), L('Previsione', 'Forecasting')], [L('Prodotti consigliati', 'Recommended products'), L('Raccomandazione', 'Recommendation')], [L('Riconoscere volti', 'Recognising faces'), L('Visione', 'Vision')], [L('Riassunto di un testo', 'Text summary'), L('Linguaggio', 'Language')]], L('Ogni problema il suo tipo.', 'Each problem its type.')),
            dFlash(pFlash(), [[L('Per decisioni sanitarie serve un controllo umano', 'Health decisions need human oversight'), true], [L('L’AI Act riguarda solo i videogiochi', 'The AI Act only covers video games'), false], [L('Senza dati sufficienti il ML funziona male', 'Without enough data ML works poorly'), true], [L('Ogni problema si risolve meglio con l’AI', 'Every problem is best solved with AI'), false]], L('Lo strumento giusto al posto giusto.', 'The right tool in the right place.')),
        ]),
    ],
];
